(function () {
  function isTyping(el) {
    if (!el) return false;
    const tag = el.tagName;
    return tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT" || el.isContentEditable;
  }
  // When fullscreen turns on/off, re-fit the poster to the new viewport.
  // The #poster-stage controller (defined at the very end of <body>) owns the
  // transform; here we just ask it to recompute. It scales box + content
  // together, so fullscreen fills the screen with the whole poster visible.
  function syncPosterFit() {
    if (window.__fitPosterStage) window.__fitPosterStage();
  }
  document.addEventListener("fullscreenchange", syncPosterFit);
  document.addEventListener("keydown", (e) => {
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    if (isTyping(e.target)) return;
    const k = e.key.toLowerCase();
    if (k === "s") {
      e.preventDefault();
      if (document.fullscreenElement) {
        document.exitFullscreen();
      } else if (document.documentElement.requestFullscreen) {
        document.documentElement.requestFullscreen().catch(err => console.warn("fullscreen failed", err));
      }
    } else if (k === "a") {
      e.preventDefault();
      document.body.classList.toggle("show-listen");
    } else if (k === "d") {
      e.preventDefault();
      window.__togglePosterDebug && window.__togglePosterDebug();
    }
  });
})();



// Debug overlay: bounding boxes + per-section/per-column size labels.
// Toggled by `d` (see keybindings script above). The CSS in <style> already
// paints the outlines via `body.debug`; this script computes and stamps
// numeric labels on first toggle, and re-stamps on every subsequent toggle
// so the values stay accurate if the poster content changed.
//
// Estimator deltas: if a sibling file named `poster_debug.json` sits next
// to this HTML and contains `{ columns: [{ index, sections: [{ id, used }] }] }`
// (the exact shape `measure_layout.js --json` already emits), each section
// badge gains an "est=NNNpx (Δ±NN)" line so you can see where the estimator
// is off. Loaded lazily on first toggle; missing file is silent.
(function () {
  let estimates = null;          // { "problem": estPx, ... } once loaded
  let estimatesTried = false;

  function loadEstimates(cb) {
    if (estimatesTried) { cb(); return; }
    estimatesTried = true;
    // Resolve sibling URL; works for file:// too (fetch may fail there — that's OK).
    const url = new URL("poster_debug.json", document.baseURI).toString();
    fetch(url).then(r => r.ok ? r.json() : null).then(j => {
      if (!j || !Array.isArray(j.columns)) { cb(); return; }
      estimates = {};
      for (const c of j.columns) {
        for (const s of (c.sections || [])) {
          if (s && s.id) estimates[s.id] = s.used;
        }
      }
      cb();
    }).catch(() => cb());
  }

  function clearBadges() {
    document.querySelectorAll(".dbg-badge, .dbg-bbox").forEach(n => n.remove());
  }

  // Stamp two rectangles per section onto the .poster: the card border-box
  // and the content union (children excluding chrome). Coordinates are
  // poster-local CSS pixels — the same frame `check_poster.py slack`
  // reports — so the visible boxes match the JSON the staged-fill gate
  // reads. Drawn as siblings of the column grid inside .poster, NOT as
  // children of each section, so the absolute positioning resolves
  // against one stable origin.
  function stampBboxes() {
    const poster = document.querySelector(".poster");
    if (!poster) return;
    const pr = poster.getBoundingClientRect();
    // The #poster-stage controller scales .poster by `transform: scale(s)` to
    // fit the window, so getBoundingClientRect() returns post-transform SCREEN
    // pixels. offsetWidth is the untransformed layout width (always the 5760
    // canvas), so s = pr.width / offsetWidth recovers the live scale. Divide
    // every screen-space delta by s to get canvas-local coords that (a) match
    // check_poster.py slack's JSON and (b) render correctly once re-scaled by
    // the transform: the .dbg-bbox divs are appended INSIDE the scaled .poster,
    // so a value left in screen px would be scaled a SECOND time -> the s^2
    // shrink-into-the-top-left bug. In the print viewport s===1 (no-op).
    const s = poster.offsetWidth ? pr.width / poster.offsetWidth : 1;
    // Counter-scale all debug chrome (badges + bbox labels) by 1/s so the text
    // stays a constant on-screen size despite the stage's transform: scale(s).
    // CSS reads it as `calc(<pt> * var(--dbg-scale))`. s===1 at print -> no-op.
    poster.style.setProperty("--dbg-scale", (s > 0 ? 1 / s : 1).toFixed(4));
    const r2 = (n) => Math.round(n * 10) / 10;
    const toLocal = (r) => ({
      x: r2((r.left - pr.left) / s), y: r2((r.top - pr.top) / s),
      w: r2(r.width / s),            h: r2(r.height / s),
    });
    // Make sure the .poster is positioned so our absolute rects anchor here.
    // The templates set `.poster` to no explicit position; flip to relative
    // only while debugging so we don't disturb the print layout.
    poster.style.position = poster.style.position || "relative";
    document.querySelectorAll(".section[data-section]").forEach(sec => {
      const id = sec.getAttribute("data-section");
      const card = toLocal(sec.getBoundingClientRect());
      // Content union: same rule as check_poster.py slack — DEEP walk over
      // every descendant (minus .listen-btn and debug chrome). The deep walk
      // matters when a descendant overflows an intermediate wrapper — e.g.
      // <figure> inside .method-body inside .section: the wrapper's
      // getBoundingClientRect() reports its allocated flex box, not the
      // overflowing figure, so a direct-children union would silently report
      // FULL while the figure visibly bleeds into the next card. The deep
      // walk catches it and the badge's verdict matches the staged-fill gate.
      let l = +Infinity, t = +Infinity, r = -Infinity, b = -Infinity, any = false;
      const walk = (el) => {
        if (!el.classList) return;
        if (el.classList.contains("listen-btn")) return;
        if (el.classList.contains("dbg-badge"))  return;
        if (el.classList.contains("dbg-bbox"))   return;
        const rc = el.getBoundingClientRect();
        if (rc.width > 0 || rc.height > 0) {
          l = Math.min(l, rc.left);  t = Math.min(t, rc.top);
          r = Math.max(r, rc.right); b = Math.max(b, rc.bottom);
          any = true;
        }
        Array.from(el.children).forEach(walk);
      };
      Array.from(sec.children).forEach(walk);
      const content = any ? toLocal({left:l, top:t, right:r, bottom:b,
                                     width:r-l, height:b-t}) : null;
      let fullStr = null;
      if (content && card && card.h > 0) {
        const fr = (content.y + content.h - card.y) / card.h;
        let verdict;
        if (fr > 1.10)       verdict = "OVERFLOW";
        else if (fr >= 1.00) verdict = "SPILLAGE";
        else if (fr >= 0.90) verdict = "FULL";
        else if (fr >= 0.70) verdict = "SPARSE";
        else                 verdict = "EMPTY";
        fullStr = `ratio=${(fr * 100).toFixed(1)}%  [${verdict}]`;
      }
      const draw = (cls, box, extra) => {
        if (!box) return;
        const el = document.createElement("div");
        el.className = "dbg-bbox " + cls;
        el.style.left   = box.x + "px";
        el.style.top    = box.y + "px";
        el.style.width  = box.w + "px";
        el.style.height = box.h + "px";
        const label = document.createElement("div");
        label.className = "dbg-bbox-label";
        const tag = cls === "dbg-bbox-card" ? "card"
                  : cls === "dbg-bbox-figure" ? "figure" : "content";
        let txt = `${id} ${tag}  x=${box.x} y=${box.y} w=${box.w} h=${box.h}`;
        if (extra) txt += "  " + extra;
        label.textContent = txt;
        el.appendChild(label);
        poster.appendChild(el);
      };
      draw("dbg-bbox-card",    card, null);
      draw("dbg-bbox-content", content, fullStr);
      // Per-figure bbox: (x,y,w,h) plus the width ratio against the section
      // card (w_figure / w_section). The ratio is the lever the staged-fill
      // loop's figure-sizing tier reasons about, so surface it on-screen too.
      sec.querySelectorAll("figure").forEach(fig => {
        const rc = fig.getBoundingClientRect();
        if (rc.width === 0 && rc.height === 0) return;
        const box = toLocal(rc);
        const ratio = card && card.w > 0 ? box.w / card.w : 0;
        draw("dbg-bbox-figure", box, `ratio=${(ratio * 100).toFixed(1)}% w/w_section`);
      });
    });
  }

  function stampBadges() {
    clearBadges();
    // Column badges — slackRatio from the column's contentBox.
    document.querySelectorAll(".columns > .col").forEach((col, i) => {
      const cs = getComputedStyle(col);
      const padT = parseFloat(cs.paddingTop) || 0;
      const padB = parseFloat(cs.paddingBottom) || 0;
      const inner = col.clientHeight - padT - padB;
      let used = 0;
      const kids = Array.from(col.children).filter(el => !el.classList.contains("dbg-badge"));
      kids.forEach(el => { used += el.offsetHeight; });
      // Approximate row-gap contribution.
      const gap = parseFloat(cs.rowGap || cs.gap) || 0;
      if (kids.length > 1) used += gap * (kids.length - 1);
      const slack = inner - used;
      const ratio = inner > 0 ? slack / inner : 0;
      const badge = document.createElement("div");
      badge.className = "dbg-badge dbg-col " + (ratio < -0.02 ? "over" : (ratio <= 0.08 ? "ok" : ""));
      badge.textContent = `col${i}  used=${Math.round(used)} / ${Math.round(inner)}  slack=${(ratio*100).toFixed(1)}%`;
      // The .col is currently `display: flex` with no positioning — set it to
      // relative locally so the absolute badge anchors to the column box.
      col.style.position = "relative";
      col.appendChild(badge);
    });
    // Section badges — actual offsetHeight, plus estimator delta when available.
    document.querySelectorAll(".section[data-section]").forEach(sec => {
      const id = sec.getAttribute("data-section");
      const actual = sec.offsetHeight;
      // full_ratio = (y_content - y_section + h_content) / h_section
      // i.e. how far down the card the content bottom reaches, as a fraction
      // of the full card height (padding included). Complements `fillRatio`
      // (which uses the padding box) by accounting for the card's own padding —
      // useful for spotting cards where content fills the padded region but
      // the surrounding padding still makes the card look mostly empty.
      const secRect = sec.getBoundingClientRect();
      // secRect (and the child rects below) are post-transform SCREEN px, but
      // `actual` is offsetHeight (untransformed layout px). Recover the stage
      // scale so the screen-space content bottom can be converted back to
      // layout px before dividing by `actual` — otherwise fullRatio is off by
      // the scale factor in a scaled browser window. s===1 in the print view.
      const posterEl = document.querySelector(".poster");
      const sBox = posterEl ? posterEl.getBoundingClientRect() : null;
      const sc = (posterEl && posterEl.offsetWidth) ? sBox.width / posterEl.offsetWidth : 1;
      let cl = +Infinity, ct = +Infinity, cr = -Infinity, cb = -Infinity, hasContent = false;
      // Deep walk -- mirrors `check_poster.py slack` so the per-section badge's
      // fullRatio matches the staged-fill gate even when a descendant overflows
      // an intermediate wrapper (e.g. <figure> in .method-body in .section).
      const walk2 = (el) => {
        if (!el.classList) return;
        if (el.classList.contains("listen-btn")) return;
        if (el.classList.contains("dbg-badge"))  return;
        if (el.classList.contains("dbg-bbox"))   return;
        const rc = el.getBoundingClientRect();
        if (rc.width > 0 || rc.height > 0) {
          cl = Math.min(cl, rc.left);  ct = Math.min(ct, rc.top);
          cr = Math.max(cr, rc.right); cb = Math.max(cb, rc.bottom);
          hasContent = true;
        }
        Array.from(el.children).forEach(walk2);
      };
      Array.from(sec.children).forEach(walk2);
      const badge = document.createElement("div");
      badge.className = "dbg-badge dbg-section";
      let html = `${id}  ${Math.round(actual)}px`;
      if (hasContent && actual > 0) {
        const fullRatio = ((cb - secRect.top) / sc) / actual;
        // Verdict label lives on the content bbox below — keep the
        // per-section badge compact.
        html += `  ratio=${(fullRatio * 100).toFixed(1)}%`;
      }
      if (estimates && estimates[id] != null) {
        const est = estimates[id];
        const delta = Math.round(actual - est);
        const cls = delta >= 0 ? "dbg-delta-pos" : "dbg-delta-neg";
        const sign = delta >= 0 ? "+" : "";
        html += ` <span class="${cls}">est=${est} Δ${sign}${delta}</span>`;
      }
      badge.innerHTML = html;
      sec.appendChild(badge);
    });
    stampBboxes();
  }

  window.__togglePosterDebug = function () {
    const enabling = !document.body.classList.contains("debug");
    document.body.classList.toggle("debug");
    if (enabling) {
      loadEstimates(() => stampBadges());
    } else {
      clearBadges();
    }
  };

  // Live-update on resize while debug is active so badge numbers stay honest.
  let raf = 0;
  window.addEventListener("resize", () => {
    if (!document.body.classList.contains("debug")) return;
    cancelAnimationFrame(raf);
    raf = requestAnimationFrame(stampBadges);
  });
})();


// Per-element debug layer (extends the `d`-key overlay) -- FANCY edition.
// On top of the per-section card/content/figure boxes, draw a rounded,
// TYPE-COLORED box around each DIRECT child element of every section (figure =
// violet, list = teal, text = blue, heading = dashed gray), label it with its
// tag + the whitespace GAP below it, and spotlight the one element that holds
// the section's slack with a glowing orange box + a "SLACK > GROW" pill -- the
// growable element the fill loop should target. Mirrors check_poster.py slack's
// per-element localization. Headings are never the slack element.
(function () {
  const S = document.createElement("style");
  S.textContent = `
    .dbg-bbox-elem {
      border: 1.5px solid var(--de-c, rgba(58,110,232,0.88));
      background: var(--de-fill, rgba(58,110,232,0.06));
      border-radius: calc(3pt * var(--dbg-scale,1));
      box-shadow: inset 0 0 0 1px rgba(255,255,255,0.22); z-index: 61; }
    .dbg-bbox-elem.de-fig  { --de-c: rgba(150,70,210,0.92); --de-fill: rgba(150,70,210,0.07); }
    .dbg-bbox-elem.de-head { --de-c: rgba(120,130,152,0.72); --de-fill: rgba(120,130,152,0.03); border-style: dashed; }
    .dbg-bbox-elem.de-list { --de-c: rgba(16,160,148,0.90); --de-fill: rgba(16,160,148,0.06); }
    .dbg-bbox-elem.de-text { --de-c: rgba(58,110,232,0.88); --de-fill: rgba(58,110,232,0.06); }
    .dbg-elem-label {
      position: absolute; left: calc(-1.5pt * var(--dbg-scale,1)); top: calc(-1.5pt * var(--dbg-scale,1));
      font-family: ui-monospace, "JetBrains Mono", Menlo, monospace;
      font-size: calc(5.4pt * var(--dbg-scale,1)); font-weight: 800; line-height: 1.15;
      padding: calc(1pt * var(--dbg-scale,1)) calc(3.5pt * var(--dbg-scale,1));
      white-space: nowrap; color: #fff; background: var(--de-c, rgba(58,110,232,0.95));
      border-radius: calc(3pt * var(--dbg-scale,1)) calc(3pt * var(--dbg-scale,1)) calc(3pt * var(--dbg-scale,1)) 0;
      box-shadow: 0 calc(1pt * var(--dbg-scale,1)) calc(3pt * var(--dbg-scale,1)) rgba(0,0,0,0.28);
      letter-spacing: .02em; }
    .dbg-bbox-elem.dbg-slack {
      border: calc(3pt * var(--dbg-scale,1)) solid rgba(232,120,0,0.98);
      --de-fill: rgba(255,178,38,0.13); background: var(--de-fill);
      box-shadow: 0 0 calc(11pt * var(--dbg-scale,1)) rgba(232,120,0,0.5),
                  inset 0 0 0 1px rgba(255,255,255,0.3); z-index: 63; }
    .dbg-bbox-elem.dbg-slack .dbg-elem-label { background: rgba(232,120,0,0.98); }
    .dbg-slack-pill {
      position: absolute; right: calc(2pt * var(--dbg-scale,1)); bottom: calc(2pt * var(--dbg-scale,1));
      font-family: ui-monospace, monospace; font-size: calc(5.4pt * var(--dbg-scale,1)); font-weight: 900;
      padding: calc(1.5pt * var(--dbg-scale,1)) calc(4.5pt * var(--dbg-scale,1));
      background: rgba(232,120,0,0.98); color: #fff; border-radius: 99pt;
      box-shadow: 0 calc(1pt * var(--dbg-scale,1)) calc(4pt * var(--dbg-scale,1)) rgba(0,0,0,0.32);
      white-space: nowrap; z-index: 64; letter-spacing: .03em; }
    body:not(.debug) .dbg-bbox-elem, body:not(.debug) .dbg-slack-pill { display: none; }
  `;
  document.head.appendChild(S);

  function stampElements() {
    const poster = document.querySelector(".poster");
    if (!poster) return;
    poster.querySelectorAll(".dbg-bbox-elem").forEach(n => n.remove());
    const pr = poster.getBoundingClientRect();
    const s  = poster.offsetWidth ? pr.width / poster.offsetWidth : 1;
    const toLocal = r => ({ x: (r.left - pr.left) / s, y: (r.top - pr.top) / s,
                            w: r.width / s, h: r.height / s });
    document.querySelectorAll(".section[data-section]").forEach(sec => {
      const kids = Array.from(sec.children).filter(k => k.classList
        && !k.classList.contains("listen-btn") && !k.classList.contains("dbg-badge")
        && !k.classList.contains("dbg-bbox") && !k.classList.contains("dbg-bbox-elem"));
      const boxes = kids.map(k => ({
        tag: k.tagName.toLowerCase(), box: toLocal(k.getBoundingClientRect()),
        isFig: (k.tagName === "FIGURE" || !!k.querySelector("figure")),
      })).filter(b => b.box.w > 1 && b.box.h > 1);
      boxes.sort((a, b) => a.box.y - b.box.y);
      const padB = parseFloat(getComputedStyle(sec).paddingBottom) || 0;
      const sL = toLocal(sec.getBoundingClientRect());
      const cardBottom = sL.y + sL.h - padB;
      let maxGap = -1, maxIdx = -1;
      boxes.forEach((b, i) => {
        const bot = b.box.y + b.box.h;
        b.gap = Math.max(0, (i + 1 < boxes.length) ? boxes[i + 1].box.y - bot : cardBottom - bot);
        if (!["h1", "h2", "h3"].includes(b.tag) && b.gap > maxGap) { maxGap = b.gap; maxIdx = i; }
      });
      boxes.forEach((b, i) => {
        const isHead = ["h1", "h2", "h3"].includes(b.tag);
        const typeCls = b.isFig ? "de-fig" : isHead ? "de-head"
                       : (b.tag === "ul" || b.tag === "ol") ? "de-list" : "de-text";
        const d = document.createElement("div");
        d.className = "dbg-bbox dbg-bbox-elem " + typeCls + (i === maxIdx ? " dbg-slack" : "");
        d.style.left = b.box.x + "px"; d.style.top = b.box.y + "px";
        d.style.width = b.box.w + "px"; d.style.height = b.box.h + "px";
        const L = document.createElement("div");
        L.className = "dbg-elem-label";
        L.textContent = b.tag + "  ·  gap " + Math.round(b.gap) + "px";
        d.appendChild(L);
        if (i === maxIdx) {
          const pill = document.createElement("div");
          pill.className = "dbg-slack-pill";
          pill.textContent = b.isFig ? "SLACK ▸ ENLARGE FIGURE" : "SLACK ▸ GROW THIS";
          d.appendChild(pill);
        }
        poster.appendChild(d);
      });
    });
  }

  const orig = window.__togglePosterDebug;
  window.__togglePosterDebug = function () {
    if (orig) orig();
    if (document.body.classList.contains("debug")) setTimeout(stampElements, 40);
    else document.querySelectorAll(".dbg-bbox-elem").forEach(n => n.remove());
  };
})();


// Resize each <figure> so its inner <img> fills the figure box edge-to-edge
// (no letterboxing). See poster_full_template for the full rationale.
(function () {
  function fit(img) {
    const fig = img.closest('figure');
    if (!fig) return;
    const nw = img.naturalWidth, nh = img.naturalHeight;
    if (!nw || !nh) return;
    const cap = fig.querySelector('figcaption');
    const section = fig.closest('.section');
    // Collapse the figure to a sliver BEFORE measuring, so a grow section
    // (flex: 1 1 auto) settles to its stable flex-allocated height instead of
    // ballooning around the full-size image -- otherwise section.bottom is
    // circular and over-reports the budget, the image isn't shrunk enough, and
    // its caption overflows the figure box where `figure{overflow:hidden}`
    // clips it. Clearing alignSelf lets the collapsed figure stretch to the
    // section's full content width (not shrink-wrap to the caption), so availW
    // is the true available width. See poster_full_template for the full
    // rationale.
    img.style.width = '1px'; img.style.height = '1px'; img.style.flex = '0 0 auto';
    fig.style.maxWidth = ''; fig.style.maxHeight = '';
    // Reset the pinned width/height/flex too (see the fit() commit below).
    // The pin shrinks the figure box to the painted-image AR; if a leftover
    // pin from a previous pass survives this collapse step, the new
    // `figRect = fig.getBoundingClientRect()` reads the old pin (not the
    // true available width), and fit() locks the figure at the stale size
    // even after the column geometry changes.
    fig.style.width = ''; fig.style.height = ''; fig.style.flex = '';
    fig.style.alignSelf = '';
    const figRect = fig.getBoundingClientRect();
    const availW = figRect.width;
    let budgetH = figRect.height;
    if (section) {
      const scs = getComputedStyle(section);
      const sBottom = section.getBoundingClientRect().bottom
                    - (parseFloat(scs.paddingBottom) || 0)
                    - (parseFloat(scs.borderBottomWidth) || 0);
      budgetH = sBottom - figRect.top;
    }
    // Figure budget floor (generalized, applies to ALL section figures,
    // not just Method). The fit() collapse-pass shrinks the figure to 1px
    // to measure available space -- but for a section that doesn't carry
    // `.grow` (e.g., Key Result sitting below a tall table), the section
    // auto-height collapses with the figure, dropping budgetH to ~caption-
    // only. The pin step then locks the figure at a ~15x60px stripe whose
    // figcaption wraps to one-character-per-line. Symptom: invisible
    // figure with vertically-compressed caption.
    //
    // Floor the budget at MIN_FIG_BUDGET (24% canvas for Method, 15% for
    // others) so the figure has a guaranteed minimum vertical slot, CAP-
    // by-column-siblings so it can't overflow the section bottom.
    // .method-horizontal exempt (row layout already gives tall slot).
    const inMethod = fig.parentElement
                  && fig.parentElement.classList
                  && fig.parentElement.classList.contains('method-body');
    const inMethodRow = inMethod
                  && fig.parentElement.classList.contains('method-horizontal');
    if (!inMethodRow && section) {
      const poster = section.closest('.poster');
      const canvasH = poster ? poster.clientHeight : 3456;
      const FIG_MIN_RATIO = 0.90;
      // HARD floor: a figure never shrinks below FIG_MIN_RATIO fill on its
      // wider axis (width-fill height for non-Method; 24% canvas for Method).
      // NO column cap: a too-tight column OVERFLOWS instead, and the fill loop
      // resolves that by trimming text -- figures are immovable.
      let MIN_FIG_BUDGET = inMethod ? 0.24 * canvasH
                         : Math.min(0.9 * canvasH, FIG_MIN_RATIO * availW * nh / nw);
      if (budgetH < MIN_FIG_BUDGET) budgetH = MIN_FIG_BUDGET;
    }
    if (availW <= 0 || budgetH <= 0) return;
    const arImg = nw / nh;
    // Width-OR-height sizing: a figure should fill 80-100% of the section on
    // at least one axis -- either width OR the vertical room flexbox handed
    // it, not necessarily both. Plain AR-preserving contain fit: start
    // full-width; if too tall for the room, shrink to fit height instead.
    //
    // A one-line caption at full column width wraps to two once the image is
    // pinned narrower, so caption room can't be reserved up front (doing so
    // under-reserves it and the second line gets clipped). Measure the
    // caption ONCE at availW (the full slot width), pin the AR-preserving
    // image, then RE-MEASURE the caption at the pinned width to set the true
    // figure box height. We deliberately do NOT iterate `width <-> caption-
    // height`: if we did, a narrow w would force the caption to wrap into
    // more lines, which ate into availH, which shrank w further, which
    // wrapped the caption taller again -- a spiral that converged to a
    // ~100px-wide stamp with a 6-line caption. See poster_full_template
    // commentary for the longer rationale.
    const capGap = cap ? (parseFloat(getComputedStyle(cap).marginTop) || 0) : 0;
    let capH = 0;
    if (cap) {
      // Measure-pass: width = availW, image collapsed.
      img.style.width = '1px'; img.style.height = '1px'; img.style.flex = '0 0 auto';
      fig.style.maxWidth = availW + 'px'; fig.style.maxHeight = '';
      const cs = getComputedStyle(cap);
      capH = cap.getBoundingClientRect().height + (parseFloat(cs.marginBottom) || 0);
    }
    const availH = Math.max(1, budgetH - capH - capGap - 2);
    // AR-preserving contain fit: start at full width; if too tall, shrink to availH.
    let w = availW, h = w / arImg;
    if (h > availH) { h = availH; w = h * arImg; }
    // Tier-5 image-scale override (see poster_full_template for rationale).
    const raw = parseFloat(img.getAttribute('data-fill-scale'));
    const scale = Number.isFinite(raw) ? Math.min(1.0, Math.max(0.8, raw)) : 1.0;
    w *= scale; h *= scale;
    img.style.width  = w + 'px';
    img.style.height = h + 'px';
    img.style.flex   = '0 0 auto';
    // Pin the figure box to the AR-preserving width, then RE-MEASURE the
    // caption at that pinned width. The caption may wrap taller inside the
    // narrower box than it did at availW; without this re-measure the figure
    // box reserves too little height and the caption visibly bleeds past the
    // bottom border (which `figure { overflow: visible }` allows) -- the
    // section's deep-walk content union then reads it as content past the
    // section border (SPILLAGE / OVERFLOW) even though the image sits
    // cleanly inside the card.
    fig.style.maxWidth  = w + 'px';
    fig.style.maxHeight = '';
    fig.style.width     = w + 'px';
    fig.style.height    = '';
    fig.style.flex      = '0 0 auto';
    let trueCapH = capH;
    if (cap) {
      const cs = getComputedStyle(cap);
      trueCapH = cap.getBoundingClientRect().height
               + (parseFloat(cs.marginBottom) || 0);
    }
    const figH = h + trueCapH + capGap + 2;
    fig.style.maxHeight = figH + 'px';
    fig.style.height    = figH + 'px';
    // (Width/height/flex pinning happened above with trueCapH; nothing left
    // to do here. Pinning matters because `figure { flex: 1 1 auto }` inside
    // a column-flex parent lets the box stretch wider than the AR-preserving
    // slot, and `figure img { width:100%; height:100%; max-height:100% }`
    // then clamps the img to the stretched parent -- `object-fit: contain`
    // paints a letterboxed image at ~50% on both axes, tripping FIG/NARROW.)
    fig.style.alignSelf = 'center';
  }
  function fitAll() {
    // Scope explicitly to figures INSIDE a section card (the only place a
    // method/motivation figure lives). Excludes titlebar QR tiles — which are
    // also `<figure>` elements but must keep their fixed CSS size; the measure
    // pass below sets `img.style.width = '1px'` inline, which would otherwise
    // collapse the QRs to ~48px (an inline style beats any CSS rule).
    document.querySelectorAll('.section figure img').forEach(img => {
      if (img.complete && img.naturalWidth) fit(img);
      else img.addEventListener('load', () => relayout(), { once: true });
    });
  }
  // `fit()` reads geometry via getBoundingClientRect(), which an ancestor
  // `transform: scale()` would distort. So every relayout runs in the UNSCALED
  // state: the #poster-stage controller clears its transform, we fit figures at
  // true 1:1 size, then it re-applies the scale. __fitPosterStage() is defined
  // by the controller IIFE at the end of <body>; if it hasn't registered yet
  // (first synchronous call), just fit directly.
  function relayout() {
    if (window.__fitPosterStage) window.__fitPosterStage(fitAll);
    else fitAll();
  }
  if (document.readyState === 'complete') relayout();
  else window.addEventListener('load', relayout);
  let raf = 0;
  window.addEventListener('resize', () => {
    cancelAnimationFrame(raf);
    raf = requestAnimationFrame(relayout);
  });
})();


// #poster-stage controller: scale the WHOLE poster (box + content together)
// to fit the window, in both normal and fullscreen view. This is what makes
// the on-screen preview match the printed PDF at any window size.
//
// The poster lays out at its true fixed canvas (5760x3456px = 60x36in @96ppi).
// We compute scale = min(winW/5760, winH/3456) and apply `transform: scale()`
// to .poster, sizing #poster-stage to the scaled footprint so the page centers
// with no scrollbars. Because the transform scales the rendered element, fonts,
// padding, figures — everything — shrink as one locked unit; no reflow, so the
// layout stays pixel-identical to the PDF.
//
// Print-safe by construction: under Chromium print emulation the viewport IS
// 5760x3456, so scale === 1 (identity). render_poster.py / check_poster.py see
// the untransformed canvas and the PDF/PNG export is byte-for-byte unchanged.
// render_poster.py's own 0.35x thumbnail transform is applied AFTER this (no
// resize event fires to clobber it), so the PNG is unaffected too.
(function () {
  const CANVAS_W = 5760, CANVAS_H = 3456;  // 60x36in at 96ppi
  const stage  = document.getElementById('poster-stage');
  const poster = stage && stage.querySelector('.poster');
  if (!stage || !poster) return;

  let applying = false;
  // Apply the fit. Optional `beforeScale` callback runs while the poster is
  // UNSCALED (transform cleared) — figure-fitting needs true geometry. We then
  // re-apply the scale. The `applying` guard stops the resize listener from
  // re-entering when beforeScale itself triggers a synchronous reflow.
  function apply(beforeScale) {
    if (applying) return;
    applying = true;
    try {
      poster.style.transform = 'none';
      if (typeof beforeScale === 'function') beforeScale();
      const scale = Math.min(
        window.innerWidth  / CANVAS_W,
        window.innerHeight / CANVAS_H,
      );
      poster.style.transform = 'scale(' + scale + ')';
      stage.style.width  = (CANVAS_W * scale) + 'px';
      stage.style.height = (CANVAS_H * scale) + 'px';
    } finally {
      applying = false;
    }
  }
  // Exposed so the figure-fit IIFE and the fullscreen handler drive a single
  // code path. They pass their fitAll() as `beforeScale` so figures are sized
  // unscaled, then the poster is re-scaled in one shot.
  window.__fitPosterStage = apply;

  apply();
  let raf = 0;
  window.addEventListener('resize', () => {
    cancelAnimationFrame(raf);
    raf = requestAnimationFrame(() => apply());
  });
})();




